import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

export interface Zone {
  id: number;
  name: string;
  status: 'available' | 'occupied' | 'maintenance' | 'closed';
  statusLabel: string;
  client?: string;
  routerModel?: string;
  ipAddress?: string;
}

@Component({
  selector: 'app-area',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './area.component.html',
  styleUrls: ['./area.component.css']
})

export class AreaComponent {

// Filtre sélectionné par défaut
  selectedFilter: 'all' | 'available' | 'occupied' | 'maintenance' | 'closed' = 'all';

  // Modal d'attribution de routeur
  isModalOpen: boolean = false;
  selectedZone: Zone | null = null;
  newRouterModel: string = '';
  newIpAddress: string = '';

  // Liste des 12 zones
  zones: Zone[] = [
    { id: 1, name: 'Zone 1', status: 'available', statusLabel: 'Disponible' },
    { id: 2, name: 'Zone 2', status: 'occupied', statusLabel: 'Occupé', client: 'Abonné Fibre #402', routerModel: 'ZTE H268N', ipAddress: '192.168.1.10' },
    { id: 3, name: 'Zone 3', status: 'maintenance', statusLabel: 'En maintenance' },
    { id: 4, name: 'Zone 4', status: 'available', statusLabel: 'Disponible' },
