  // Obtenir la liste des zones filtrées
  get filteredZones(): Zone[] {
    if (this.selectedFilter === 'all') return this.zones;
    return this.zones.filter(zone => zone.status === this.selectedFilter);
  }

  // Clic sur une zone : ouvrir la modale d'ajout de routeur
  onZoneClick(zone: Zone): void {
    if (zone.status === 'closed') {
      alert('Cette zone est fermée par l administration.');
      return;
    }
    this.selectedZone = zone;
    this.newRouterModel = zone.routerModel || '';
    this.newIpAddress = zone.ipAddress || '';
    this.isModalOpen = true;
  }

  // Fermer la modale
  closeModal(): void {
    this.isModalOpen = false;
    this.selectedZone = null;
  }

  // Sauvegarder la configuration du routeur pour la zone
  saveRouterConfig(): void {
    if (this.selectedZone) {
      this.selectedZone.routerModel = this.newRouterModel;
      this.selectedZone.ipAddress = this.newIpAddress;

      // Si la zone était disponible, passage en statut 'occupied' après configuration
      if (this.selectedZone.status === 'available' && this.newRouterModel) {
        this.selectedZone.status = 'occupied';
        this.selectedZone.statusLabel = 'Occupé';
      }
    }
    this.closeModal();
  }
}
